// Настройки шаблона: меняются здесь, в одном месте.
const CONFIG = {
  llm_base_url: 'https://api.openai.com/v1',   // любой OpenAI-совместимый API
  llm_model: 'gpt-4o-mini',
  threshold: 0.7,                               // порог уверенности для автоответа
  manager_chat_id: 'MANAGER_CHAT_ID',           // Telegram-чат менеджера
};

const raw = $input.first().json;
const body = raw.body || raw;
const message = String(body.message || body.text || '').replace(/\s+/g, ' ').trim().slice(0, 2000);
const now = new Date();
const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');

return [{
  json: {
    ...CONFIG,
    message,
    session_id: String(body.session_id || 'anon-' + now.getTime()),
    channel: String(body.channel || 'web'),
    customer_name: String(body.name || ''),
    ticket_id: 'T-' + stamp + '-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
    received_at: now.toISOString(),
  },
}];

// База знаний магазина посуды «Северный Ковш».
// В рабочем проекте заменяется запросом к Notion, Google Docs или векторной базе.
const KB = [
  { id: 'kb-01', title: 'Доставка по России', keywords: ['доставка', 'доставить', 'курьер', 'привезти', 'сдэк', 'почта', 'стоимость доставки'],
    text: 'Доставляем курьером и в пункты выдачи по всей России. По городу 350 ₽, бесплатно от 5000 ₽. В регионы 2–7 рабочих дней, стоимость считается в корзине.' },
  { id: 'kb-02', title: 'Самовывоз', keywords: ['самовывоз', 'забрать', 'склад', 'адрес', 'пункт'],
    text: 'Самовывоз со склада: ул. Заводская, 12, пн–пт 10:00–19:00. Заказ готов через 2 часа после подтверждения, хранится 5 дней.' },
  { id: 'kb-03', title: 'Способы оплаты', keywords: ['оплата', 'оплатить', 'карта', 'сбп', 'наличные', 'счёт', 'счет'],
    text: 'Оплата картой или по СБП на сайте, наличными или картой при получении. Для юрлиц выставляем счёт.' },
  { id: 'kb-04', title: 'Возврат и обмен товара', keywords: ['возврат', 'вернуть', 'обмен', 'обменять', 'не подошел', 'не подошёл'],
    text: 'Товар надлежащего качества можно вернуть в течение 14 дней, если сохранены упаковка и чек. Оформите заявку в личном кабинете, деньги вернём в течение 10 дней после получения товара.' },
  { id: 'kb-05', title: 'Гарантия', keywords: ['гарантия', 'гарантийный', 'брак', 'сломался', 'сломалась', 'дефект', 'трещина'],
    text: 'Гарантия на посуду 12 месяцев, на чугун 5 лет. При браке пришлите фото и номер заказа, заменим товар или вернём деньги.' },
  { id: 'kb-06', title: 'Статус заказа', keywords: ['статус', 'где заказ', 'отследить', 'трек', 'номер заказа', 'когда придет', 'когда придёт'],
    text: 'Статус и трек-номер видны в личном кабинете в разделе «Мои заказы». Трек приходит по SMS после передачи заказа в доставку.' },
  { id: 'kb-07', title: 'Уход за чугунной посудой', keywords: ['чугун', 'чугунная', 'сковорода', 'ржавчина', 'прокалить', 'уход', 'мыть'],
    text: 'Чугун моют без агрессивных средств и сразу вытирают насухо. Раз в несколько месяцев прокаливают с тонким слоем масла. Посудомоечная машина не подходит.' },
];

const stem = w => w.toLowerCase().replace(/ё/g, 'е').slice(0, 5);
const words = s => s.toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9\s]/g, ' ').split(/\s+/).filter(w => w.length >= 3);

const q = $input.first().json;
const qStems = new Set(words(q.message).map(stem));

const scored = KB.map(a => {
  const hits = a.keywords.filter(k => words(k).every(w => qStems.has(stem(w)))).length;
  return { ...a, score: Math.min(1, hits / 2) };
}).filter(a => a.score > 0).sort((a, b) => b.score - a.score).slice(0, 2);

const context = scored.length
  ? scored.map(a => `[${a.id}] ${a.title}: ${a.text}`).join('\n')
  : 'Подходящих статей не найдено.';

const llm_request = {
  model: q.llm_model,
  temperature: 0.2,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content:
      'Ты ассистент поддержки интернет-магазина. Отвечай по-русски, коротко и вежливо, только по статьям базы знаний. ' +
      'Если в статьях нет ответа, не придумывай. Верни JSON: {"answer": string, "confidence": число от 0 до 1, "article_ids": string[]}.' },
    { role: 'user', content: `Статьи базы знаний:\n${context}\n\nВопрос клиента: ${q.message}` },
  ],
};

return [{ json: { ...q, kb_hits: scored.map(a => ({ id: a.id, title: a.title, score: a.score })), kb_score: scored[0]?.score || 0, llm_request } }];

// Разбор ответа LLM и решение: автоответ или передача менеджеру.
const q = $('Поиск в базе знаний').first().json;
const res = $input.first().json;

const FORCE_WORDS = ['оператор', 'менеджер', 'человек', 'жалоб', 'претенз', 'суд', 'верните деньги'];
const text = q.message.toLowerCase();
const forced = FORCE_WORDS.find(w => new RegExp('(^|[^а-яё])' + w).test(text));

let answer = '', llmConf = 0, articleIds = [], llmError = '';
try {
  if (res.error) throw new Error(typeof res.error === 'string' ? res.error : (res.error.message || 'llm_error'));
  const content = res.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  answer = String(parsed?.answer || '').trim();
  llmConf = Math.max(0, Math.min(1, Number(parsed?.confidence) || 0));
  articleIds = Array.isArray(parsed?.article_ids) ? parsed.article_ids : [];
} catch (e) {
  llmError = String(e.message || e).slice(0, 200);
}

// Итоговая уверенность: оценка модели и совпадение с базой знаний.
const confidence = q.kb_score === 0 || llmError || !answer ? 0 : Math.round((0.6 * llmConf + 0.4 * q.kb_score) * 100) / 100;

let reason = '';
if (!q.message) reason = 'пустое сообщение';
else if (forced) reason = `клиент просит человека или жалуется («${forced}»)`;
else if (llmError) reason = 'ошибка LLM: ' + llmError;
else if (q.kb_score === 0) reason = 'нет статьи в базе знаний';
else if (confidence < q.threshold) reason = `низкая уверенность ${confidence}`;

return [{ json: {
  ...q,
  answer,
  llm_confidence: llmConf,
  article_ids: articleIds,
  confidence,
  force_handoff: Boolean(forced || llmError || !q.message),
  handoff_reason: reason,
  handoff: Boolean(reason),
} }];

