// Одна строка журнала на каждое обращение, для обеих веток.
const d = $('Оценка уверенности').first().json;
return [{ json: {
  'Дата': d.received_at,
  'Тикет': d.ticket_id,
  'Сессия': d.session_id,
  'Канал': d.channel,
  'Вопрос': d.message,
  'Статьи': d.kb_hits.map(h => h.id).join(', '),
  'Уверенность': d.confidence,
  'Результат': d.handoff ? 'Передано менеджеру' : 'Автоответ',
  'Причина передачи': d.handoff_reason,
  'Ответ': d.handoff ? '' : d.answer,
} }];

